.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul {
	margin: 0;
	padding: 15px;
	padding-bottom: 0;
	display: flex;
	flex-wrap: wrap;
	row-gap: 15px;
}

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul li {
	flex: 0 0 50%;
	max-width: 50%;
	list-style: none;
	display: flex;
}

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul li span {
	font-size: 14px;
	color: rgba(0, 0, 0, .5);
	width: 40%;
}

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul li span + span {
	font-size: 14px;
	flex: 1;
	color: black;
}
@media (max-width:576px) {

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul {
	padding-top: 0;
}

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul li {
	flex: 0 0 100%;
	max-width: 100%;
}

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul li span {
	width: 50%;
}

.v34a8bd821b9ef4102249326c0a4bcba1 .cst-panel-card ul li span + span {
	text-align: right;
}
}

widget.client_script:
api.controller = function() {
    var c = this;
    c.data.showHidegeneralBody = false;
    c.collapseAD = function(id) {
        var collSectionAD = document.getElementById(id);
        if (collSectionAD.className == 'fa fa-minus pull-right') {
            collSectionAD.className = 'fa fa-plus pull-right';
            c.data[id] = true;
        } else {
            collSectionAD.className = 'fa fa-minus pull-right';
            c.data.showHidegeneralBody = false;
            c.data[id] = false;
        }
    };
};
